// ONCO-ASCAT-001 — ASCAT male X non-PAR germline re-genotyping in ascat.aspcf / ascat.asmultipcf (B24 F58)
// Evidence: docs/Evidence/ONCO-ASCAT-001-Evidence.md (§ "Male X non-PAR re-genotyping (F58)")
// TestSpec: tests/TestSpecs/ONCO-ASCAT-001.md (M-MALEX-*, S-MALEX-*, C-MALEX-*); multi-sample ascat.aspcf one-stream driver: F65
// Source:  VanLoo-lab/ascat master, ASCAT/R/ascat.aspcf.R (ascat.aspcf: set.seed(seed); nonPAR block) and
//          ASCAT/R/ascat.asmultipcf.R (same block on the first germline); R 4.3.3 base::rank (ties.method = "random" =
//          sort.list(order(x, stats::runif(n)))) and src/main/random.c (do_sample without replacement, R_unif_index).
//
// Every expected value below is the output of the ORIGINAL R code (R 4.3.3, sourced ascat.aspcf.R + ascat.asmultipcf.R):
// ascat.aspcf / ascat.asmultipcf(ASCATobj with gender = "XY", X_nonPAR = c(2699521, 154931043) [hg19], Germline_BAF or
// ascat.gg, out.dir = NA, seed; asmultipcf penalty = 10) on the deterministic tracks generated by Simulate() — the MINSTD
// generator is reproduced verbatim in R, so both sides see bit-identical input. Selected = 1 per X non-PAR probe (in input
// order) that ASCAT re-genotyped heterozygous (row names of Tumor_BAF_segmented). Segments = runs of equal
// Tumor_LogR_segmented within a chromosome; BAF = 1 − Tumor_BAF_segmented of the first heterozygous probe of the segment (NaN = none).

namespace Seqeron.Genomics.Tests.Unit.Oncology;

[TestFixture]
public class OncologyAnalyzer_AscatMaleXNonPar_Tests
{

    // ---- Deterministic male track generator (identical R implementation in the Evidence file) ----

    /// <summary>Kind: 'A' autosome/PAR (germline het unless u &lt; pHom), 'H' forced homozygous autosome, 'X' hemizygous
    /// male X (germline BAF exactly 0/1 with probability 0.4, else within 0.05 of 0/1; tumour BAF = b ± noise).</summary>
    public sealed record Block(string Chrom, int N, long Start, long Step, char Kind, double[] R, double[] B);

    public sealed record Track(int Samples, int Seed, double PHom, bool UseGermlineBaf, int RSeed, Block[] Blocks);

    public readonly record struct Seg(string Chr, long Start, long End, double LogR, double Baf, int N, int NHet);

    public sealed record Expected(string Selected, Seg[][] Samples);

    private static Block Bl(string chrom, int n, long start, long step, char kind, params double[] rb)
    {
        int s = rb.Length / 2;
        return new Block(chrom, n, start, step, kind, rb[..s], rb[s..]);
    }

    private static Block[] XBlocks(double[] r1, double[] r2, double[] b1, double[] b2)
    {
        double[] zero = new double[r1.Length], half = Enumerable.Repeat(0.5, r1.Length).ToArray();
        return new[]
        {
            new Block("X", 30, 100000, 80000, 'A', zero, half),
            new Block("X", 300, 3000000, 400000, 'X', r1, b1),
            new Block("X", 100, 123000000, 300000, 'X', r2, b2),
            new Block("X", 20, 155000000, 10000, 'A', zero, half),
        };
    }

    private static double[] V(params double[] v) => v;

    // M1: Germline_BAF branch, seed 1; 159 exact 0/1 ties all inside the k = 281 selected (autosomal het fraction 0.7033).
    private static readonly Track M1 = new(1, 11, 0.3, true, 1, new[]
    {
        Bl("1", 250, 1000, 1000, 'A', 0, 0.5), Bl("1", 150, 251000, 1000, 'A', -0.6, 0.8), Bl("2", 200, 1000, 1000, 'A', 0.3, 0.65),
    }.Concat(XBlocks(V(-0.5), V(-1.2), V(0.95), V(0.97))).ToArray());

    // M2: Germline_BAF branch, seed 7777; k = 147 < 167 exact ties (DIST = 0), so the runif tie-break decides the selection.
    private static readonly Track M2 = new(1, 22, 0.6, true, 7777, new[]
    {
        Bl("1", 300, 1000, 1000, 'A', 0, 0.5), Bl("1", 60, 301000, 1000, 'H', 0, 0.5), Bl("2", 250, 1000, 1000, 'A', 0.5, 0.7),
    }.Concat(XBlocks(V(-0.4), V(-0.4), V(0.9), V(0.9))).ToArray());

    // M3: no Germline_BAF (ascat.gg genotypes) ⇒ sample(nonPAR_index, k), seed 42.
    private static readonly Track M3 = new(1, 33, 0.35, false, 42, new[]
