        Bl("1", 300, 1000, 1000, 'A', 0, 0.5), Bl("2", 200, 1000, 1000, 'A', -0.5, 0.85),
    }.Concat(XBlocks(V(-0.5), V(0.3), V(0.95), V(0.75))).ToArray());

    // M4: Germline_BAF branch with a time-type seed, as ASCAT's default seed = as.integer(Sys.time()) produces (1760090000).
    private static readonly Track M4 = new(1, 44, 0.3, true, 1760090000, new[]
